Use a count to distinguish full from empty: the invariant is 0 ≤ count ≤ 17, with tail = (head + count) mod 17. When head equals tail, count is either 0 (empty) or 17 (full); rejected pushes leave all state unchanged. Compile with C++17 and assertions enabled, then run the executable.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) return false;
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    BoundedFIFO queue;
    int value = -1;

    assert(queue.empty());
    assert(!queue.pop(value));
    assert(value == -1);

    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
        assert(queue.size() == static_cast<std::size_t>(i + 1));
    }
    assert(queue.full());
    assert(!queue.push(999));
    assert(queue.size() == 17);

    // Exact draining order also verifies rejection preserved contents.
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    // Advance head, then wrap tail while unread values remain.
    for (int i = 0; i < 12; ++i) {
        assert(queue.push(i));
    }
    for (int i = 0; i < 8; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    for (int i = 12; i < 25; ++i) {
        assert(queue.push(i));
    }
    assert(queue.full());
    assert(!queue.push(999));
    assert(queue.size() == 17);

    // Draining crosses the array boundary as well.
    for (int i = 8; i < 25; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    std::cout << "All tests passed\n";
}
```

The lower median is 4. Copy the input and use `std::nth_element` at index `(n - 1) / 2`, leaving the caller’s array unchanged; reject empty input with `std::invalid_argument`.

For odd size n = 2m + 1, the index is m, the middle element. For even size n = 2m, the index is m − 1, the lower of the two middle elements. `std::nth_element` places the same value at that index as sorting would, including when values are duplicated.

Compile with C++17 and assertions enabled, then run the executable.

```cpp
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

int lower_median(const std::vector<int>& input) {
    if (input.empty()) {
        throw std::invalid_argument("lower_median requires nonempty input");
    }

    std::vector<int> copy = input;
    const std::size_t k = (copy.size() - 1) / 2;
    auto selected = copy.begin() +
        static_cast<std::vector<int>::difference_type>(k);
    std::nth_element(copy.begin(), selected, copy.end());
    return *selected;
}

int main() {
    const auto check = [](std::vector<int> input, int expected) {
        const std::vector<int> original = input;
        const int result = lower_median(input);
        assert(result == expected);
        assert(input == original);
    };

    check({9, 1, 4, 4, 7, 2}, 4); // Duplicates; sorted: 1,2,4,4,7,9.
    check({5, 1, 9, 3, 7}, 5);    // Odd size.
    check({8, 2, 6, 4}, 4);       // Even size: lower middle.
    check({42}, 42);              // Singleton.
    check({4, 4, 4, 4}, 4);       // All equal.

    const std::vector<int> empty;
    bool rejected = false;
    try {
        (void)lower_median(empty);
    } catch (const std::invalid_argument&) {
        rejected = true;
    }
    assert(rejected);
    assert(empty.empty());

    std::cout << "All tests passed\n";
    return 0;
}
```

No. Keeping `desired` unchanged can lose an increment: a successful retry may write the value already present.

Concrete execution, starting at 0:
1. Threads A and B both load `expected = 0` and compute `desired = 1`.
2. A successfully changes 0 to 1 and returns.
3. B’s comparison against 0 fails, updating B’s `expected` to 1 but leaving `desired = 1`.
4. B retries and successfully changes 1 to 1. Both increments return, but the count is only 1.

Recompute `desired` on every attempt. A spurious failure merely causes another retry; each successful comparison stores exactly one more than the value it compared against. Relaxed ordering suffices for this counter, and joining all threads precedes the final check; the test stays below overflow. Compile with `g++ -std=c++17 -O2 -pthread main.cpp -o test`, without `-DNDEBUG`, then run `./test`.

```cpp
#include <atomic>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <thread>
#include <vector>

void increment(std::atomic<std::uint64_t>& counter) {
    std::uint64_t expected = counter.load(std::memory_order_relaxed);
    for (;;) {
        const std::uint64_t desired = expected + 1;
        if (counter.compare_exchange_weak(
                expected, desired,
                std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return;
        }
        // Failure, including spurious failure, updates expected.
        // The next iteration recomputes desired from that value.
    }
}

int main() {
    constexpr unsigned thread_count = 8;
    constexpr std::uint64_t increments_per_thread = 100000;
    constexpr std::uint64_t expected_count =
        thread_count * increments_per_thread;

    std::atomic<std::uint64_t> counter{0};
    std::vector<std::thread> threads;
    threads.reserve(thread_count);

    for (unsigned t = 0; t < thread_count; ++t) {
        threads.emplace_back([&counter] {
            for (std::uint64_t i = 0; i < increments_per_thread; ++i) {
                increment(counter);
            }
        });
    }
    for (auto& thread : threads) {
        thread.join();
    }

    const auto actual = counter.load(std::memory_order_relaxed);
    assert(actual == expected_count);
    std::cout << "Final count: " << actual << "\nAll tests passed\n";
    return 0;
}
```
